#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
# This walkthrough's own helpers.
SITE="http://localhost:3000/fr"
PASSED=()
EMAIL=""
# The SasPay key goes to .env.local: it wins over .env (which may hold the live key) and is never committed.
ENV_FILE=".env.local"

# check "what": asks whether it worked; what didn't is listed at the end.
check() {
  if confirm "$1: did it work?"; then
    PASSED+=("$1")
  else
    SKIPPED+=("didn't work: $1")
  fi
}

# rows "SQL": prints the rows of one read-only query on the database in .env.
rows() {
  QUERY="$1" node -e '
    const { PrismaClient } = require("@prisma/client");
    const db = new PrismaClient();
    db.$queryRawUnsafe(process.env.QUERY)
      .then((r) => { if (r.length === 0) console.log("  (no rows)"); else console.table(r); })
      .catch((e) => console.error("  " + e.message))
      .finally(() => db.$disconnect());'
}

# sql "statement": runs one statement on the database in .env.
sql() {
  printf '%s' "$1" | npx prisma db execute --stdin --schema prisma/schema.prisma
}

# codes: the Codes promo on « test », with their places paid.
codes() {
  rows "SELECT c.code, c.\"reductionType\" AS type, c.\"reductionValue\" AS value, c.places,
               (SELECT count(*) FROM consultation_payment p WHERE p.\"promoCodeId\" = c.id AND p.status = 'SUCCESS') AS paid,
               (SELECT count(*) FROM consultation_payment p WHERE p.\"promoCodeId\" = c.id AND p.status = 'PENDING') AS pending,
               to_char(c.\"endsAt\" + interval '1 hour', 'DD Mon HH24:MI') AS \"ends (Douala)\", c.\"oncePerAccount\" AS once,
               (c.\"deletedAt\" IS NOT NULL) AS deleted
        FROM promo_code c ORDER BY c.\"createdAt\" DESC LIMIT 6"
}

# yours: the test aliases' payments, with their code and reduction.
yours() {
  local local_part="${EMAIL%@*}" domain="${EMAIL#*@}"
  rows "SELECT a.email, c.status, p.status AS payment, p.amount, p.discount, pc.code
        FROM consultation c JOIN account a ON a.id = c.\"accountId\"
        LEFT JOIN consultation_payment p ON p.\"consultationId\" = c.id
        LEFT JOIN promo_code pc ON pc.id = p.\"promoCodeId\"
        WHERE a.email LIKE '${local_part}+promo%@${domain}'
        ORDER BY c.\"createdAt\" DESC, p.\"createdAt\" DESC LIMIT 8"
}

alias_of() { printf '%s+promo%s@%s' "${EMAIL%@*}" "$1" "${EMAIL#*@}"; }

run_wizard() {

TOTAL_STAGES=9

banner "Walkthrough: Codes promo, Tableau de bord and checkout (#15)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before we start"
say "You'll make Codes promo in the Tableau de bord and use them at checkout, in SasPay's sandbox."
say "This follows the payment walkthrough: the sandbox key in .env.local and the price on « test »"
say "must already be there (run ./scripts/test-walkthrough-consultation-payment.sh first if not)."
warn "« test » has real people in it, and e-mails really go out: book with your own aliases."
say ""
ask EMAIL "Your e-mail (bookings use you+promo1@…, you+promo2@…)?"
EMAIL=$(printf '%s' "$EMAIL" | tr '[:upper:]' '[:lower:]')
while [[ ! "$EMAIL" =~ ^[a-z0-9._%-]+@[a-z0-9.-]+\.[a-z]{2,}$ ]]; do
  warn "That doesn't look like an e-mail address (no « + » in it)."
  ask EMAIL "Your e-mail?"
  EMAIL=$(printf '%s' "$EMAIL" | tr '[:upper:]' '[:lower:]')
done
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The database and the dev server"
if confirm "Run « npx prisma migrate deploy » and « prisma generate » now (the promo_code table)?"; then
  npx prisma migrate deploy && npx prisma generate >/dev/null && printf '  %s✓ database up to date%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("check the migrations: npx prisma migrate deploy && npx prisma generate")
fi
step "Restart « npm run dev » on feat/consultation-booking (the Prisma client changed)."
pause "Press Enter once the dev server is running again"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Tableau de bord: two codes"
open_url "http://admin.localhost:3000/codes-promo"
step "Signed in as the consultant: Facturation → « Codes promo » in the sidebar (opened for you)."
step "Nouveau code: TESTPROMO, % 50, Consultation, 2 places, no end, « Une seule fois par Compte »"
step "  ticked. « Au paiement » shows the price struck through and half of it. « Créer le code »."
step "A second one: TESTFIN, FCFA 1000, Consultation, no places, Fin = a few minutes from now."
step "Try TESTPROMO again: « Un code actif porte déjà ce nom. »; % 100: « Au plus 99 % »."
step "Mobile (Cmd+Shift+M): the codes as cards, « + Nouveau code » opens the sheet."
codes
check "Codes promo: the list and « Nouveau code »"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "At checkout: a typo, then the code"
open_url "$SITE/services/consultation"
step "Book a slot with $(alias_of 1) (signed out, number 6 77 12 34 50), go to step 3."
step "Summary: « Vous avez un code promo ? » → type TESTPROMOO, « Appliquer »: the field shakes once,"
step "  « Ce code n'existe pas. Vérifiez l'orthographe : TESTPROMO ? ». Click TESTPROMO, « Appliquer »."
step "The chip « TESTPROMO · −50 % », « Plus que 2 places sur 2 », the price struck through, the"
step "  reduction, the fee on what is left, « Payer … » for the new total."
step "Mobile: « Ajouter un code promo » opens the sheet; applied, the green card with « Retirer »."
check "Applying a code at checkout"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Paying with the code"
step "« Payer »: « C'est réservé »; the receipt shows TESTPROMO and its reduction."
yours
codes
note "Expect: the payment's amount is half the price, discount the other half; TESTPROMO paid 1."
check "A paid code counts one place, and the receipt shows it"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "« Une seule fois par Compte »"
step "Click the Vérification link in $(alias_of 1)'s inbox (it signs you in as that Compte),"
step "  then book another slot signed in. Step 3, apply TESTPROMO:"
step "  « Vous avez déjà utilisé ce code : il ne vaut qu'une fois par Compte. »"
check "A Compte can't use a once-only code twice"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "The last place, taken while you pay"
step "Two private windows, A and B. Book a slot in each: A with $(alias_of 2) and number"
step "  6 77 12 34 59 (stays pending), B with $(alias_of 3) and 6 77 12 34 50. Apply TESTPROMO in"
step "  both: one place is left (the other was paid at stage 5)."
step "A: « Payer » (number ending in 9: it stays pending and holds the last place)."
step "B: « Payer »: the « Dernière place partie » sheet, « Rien n'a été débité », the full price;"
step "  « Payer … » there pays the full price: « C'est réservé »."
yours
codes
check "The last place is never given twice"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "An ended code, and deleting one"
step "Once TESTFIN's end has passed: apply it on a new booking ($(alias_of 4)):"
step "  « Cette offre est terminée. La consultation reste à … »."
step "Tableau de bord: TESTFIN shows « Terminé ». Delete TESTPROMO: the confirmation, then it's gone."
step "Its paid reduction stays: the receipt of $(alias_of 1) still shows it."
codes
check "Ended and deleted codes"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Done"
printf '  %s✓ %s check(s) passed%s\n' "$GREEN" "${#PASSED[@]}" "$RESET"
for item in "${PASSED[@]}"; do note "    ✓ $item"; done
say ""
say "The test codes stay in « test » (deleted ones hidden). The pending payment of stage 7 never"
say "settles in the sandbox; its booking frees its slot by itself."
say ""
say "Send me what didn't work (listed below) and I'll look into it."
pause

finish
}

run_wizard "$@"; exit
